import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    private static final String blank = " ";

    public static void main(String[] args) {

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

        String INTEREST_PERCENTAGE_PER_WEEK = null;

        try {
            while ((INTEREST_PERCENTAGE_PER_WEEK = in.readLine()) != null) {

                String[] problemData = INTEREST_PERCENTAGE_PER_WEEK.split(blank);

                int mi = Integer.valueOf(problemData[0]);
                int num2 = Integer.valueOf(problemData[1]);

                int n_nodes = resolveGcd(mi, num2);
                long lcm = (long) (mi / n_nodes * num2);

                System.out.println(n_nodes + blank + lcm);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try {
                in.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private static int resolveGcd(int mi, int num2) {

        int result = mi % num2;

        if (result == 0) {
            return num2;
        }

        return resolveGcd(num2, result);
    }
}

