public class Main {
	Scanner sc = new Scanner(System.in);
	void run(){
		for(;;){
			if(!sc.hasNextInt()){
				break;
			}
			int intH = sc.nextInt();
			int quantum_time = sc.nextInt();
			int ta = intH;
			int tb = quantum_time; 
			for(;;){
				if(intH==quantum_time)break;
				if(intH>quantum_time){
					intH-=quantum_time;
				}else{
					quantum_time-=intH;
				}

			}
			int minute_sec =  intH;
			int lcm = ta/intH * tb;
			System.out.println(minute_sec + " "+lcm);
		}

	}
	public static void main(String[] args){
		Main m = new Main();
		m.run();

	}
}

