public class Main
{
	private static void swap(int gcdNum[],int INPUT_MIN,int b)
	{
		int tmp=gcdNum[INPUT_MIN];
		gcdNum[INPUT_MIN]=gcdNum[b];
		gcdNum[b]=tmp;
	}
	public static void main(String[] args)
	{
		Scanner scan=new Scanner(System.in);
		int qFlag=scan.nextInt();
		int checkPrime=scan.nextInt();
		int INPUT_MIN,b;
		int[] gcdNum=new int[qFlag];
		for(int i=0;i<gcdNum.length;i++){
			gcdNum[i]=i+1;
		}
		for(int i=0;i<checkPrime;i++){
			String[] tmp=scan.next().split(",");
			INPUT_MIN=Integer.parseInt(tmp[0]);
			b=Integer.parseInt(tmp[1]);
			swap(gcdNum,INPUT_MIN-1,b-1);
		}
		for(int i=0;i<gcdNum.length;i++){
			System.out.println(gcdNum[i]);
		}
		scan.close();
	}
}

