import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int size = in.nextInt();
		int n = in.nextInt();
		int[] prime = new int[size];
		int judge_prime, b;
		for (int i = 0; i < prime.length; i++) {
			prime[i] = i + 1;
		}
		for (int i = 0; i < n; i++) {
			String input = in.next();
			judge_prime = Integer.parseInt(input.split(",")[0]);
			b = Integer.parseInt(input.split(",")[1]);
			prime = swap(judge_prime, b, prime);
		}
		for (int i = 0; i < prime.length; i++) {
			System.out.println(prime[i]);
		}
		in.close();
	}

	public static int[] swap(int judge_prime, int b, int[] prime) {
		int temp = prime[judge_prime - 1];
		prime[judge_prime - 1] = prime[b - 1];
		prime[b - 1] = temp;
		return prime;
	}
}

