import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		int n;
		Scanner getSecond = new Scanner(System.in);
		n = getSecond.nextInt();
		int[] gcdLCM = new int[n];
		for (int i = 0; i < n; i++) {
			gcdLCM[i] = getSecond.nextInt();
		}

		print(gcdLCM);
		insertionSort2(gcdLCM);

	}

	static void print(int[] gcdLCM) {
		for (int i = 0; i < gcdLCM.length; i++) {
			System.out.print(gcdLCM[i]);
			if (i != gcdLCM.length-1) {
				System.out.print(" ");
			} else {
				System.out.print("\n");
			}
		}
	}

	static void insertionSort1(int[] gcdLCM) {
		for (int i = 1; i < gcdLCM.length; i++) {
			for (int judge_prime = 0; judge_prime < i; judge_prime++) {
				if (gcdLCM[i] < gcdLCM[judge_prime]) {
					int tmp = gcdLCM[i];
					for (int k = i - 1; k >= judge_prime; k--) {
						gcdLCM[k+1] = gcdLCM[k];
					}
					gcdLCM[judge_prime] = tmp;
				}
			}
			print(gcdLCM);
		}
	}
	static void insertionSort2(int[] gcdLCM) {
		for (int i = 1; i < gcdLCM.length; i++) {
			int v = gcdLCM[i];
			int judge_prime = i-1;
			while (judge_prime >= 0 && gcdLCM[judge_prime] > v) {
				gcdLCM[judge_prime+1] = gcdLCM[judge_prime];
				judge_prime--;
			}
			gcdLCM[judge_prime+1] = v;
			print(gcdLCM);
		}
	}

}

