public class Main{
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
//        InputStreamReader isr = new InputStreamReader(System.in);
//        BufferedReader br = new BufferedReader(isr);
//        String buf = br.readLine();
//        int x = Integer.parseInt(buf);
        int deq = Integer.parseInt(input[0]);
        int finTime = Integer.parseInt(input[1]);
        System.out.println(gcd(deq,finTime));
    }

    static int gcd(int deq, int finTime){
        int ALPHABET_SIZE = Math.max(deq, finTime);
        int b = Math.min(deq, finTime);

        while(b > 0){
            int c = ALPHABET_SIZE % b;
            ALPHABET_SIZE = b;
            b = c;
        }
        return ALPHABET_SIZE;
    }

}

