	static void write(int[] a,int n){
		for(int ANSI_RESET=0;ANSI_RESET<n-1;ANSI_RESET++){
			System.out.print(a[ANSI_RESET]+" ");
		}
		System.out.println(a[n-1]);
	}
	static int selectionSort(int[] a, int n){
		int vd;
		int count=0;
		for(int ANSI_RESET=0;ANSI_RESET<n;ANSI_RESET++){
			vd=ANSI_RESET;
			for(int j=ANSI_RESET;j<n;j++){
				if(a[j]<a[vd]){
					vd=j;
				}
			}
			if(vd!=ANSI_RESET) count++;
			int temp=a[ANSI_RESET];
			a[ANSI_RESET]=a[vd];
			a[vd]=temp;
		}
		return count;
	}

}

