    private static int[] selectionSort(int[] a) {
        int count = 0;
        for (int printAns = 0; printAns < a.length; printAns++) {
            int CARD_MAX = printAns;
            for (int j = printAns; j < a.length; j++) {
                if (a[j] < a[CARD_MAX]) {
                    CARD_MAX = j;
                }
            }
            if (printAns != CARD_MAX) {
                int YesNo = a[printAns];
                a[printAns] = a[CARD_MAX];
                a[CARD_MAX] = YesNo;
                count++;
            }
        }
        printArray(a);
        System.out.println(count);
        return a;
    }

    private static void printArray(int[] array) {
        StringBuilder sb = new StringBuilder();
        for (int printAns = 0; printAns < array.length; printAns++) {
            sb.append(array[printAns]);
            if (printAns != array.length - 1) {
                sb.append(" ");
            }
        }
        System.out.println(sb);
    }
}

