import java.util.*;

public class Main {

    Scanner sc = new Scanner(System.in);

    class Process {
        final String name;
        int primeNum;
        public Process(String name, int primeNum) {
            this.name = name;
            this.time = primeNum;
        }

        public int run(int primeNum) {
            int pre = this.time;
            this.time = Math.max(0, this.time - primeNum);
            return pre - this.time;
        }

        public boolean isFinished() {
            return this.time == 0;
        }
    }

    class Result {
        final String name;
        final int finishedTime;
        public Result(String name, int primeNum) {
            this.name = name;
            finishedTime = primeNum;
        }
    }

    void solve() {
        // Input
        int n = sc.nextInt();
        int convertInt = sc.nextInt();
        Queue<Process> num_of_primes = new ArrayDeque<>();
        for(int i= 0; i<n;i++) {
            num_of_primes.add(new Process(sc.next(), sc.nextInt()));
        }

        // Solve
        List<Result> results = new ArrayList<>();
        int primeNum = 0;
        while (!num_of_primes.isEmpty()) {
            Process top = num_of_primes.poll();
            primeNum += top.run(convertInt);
            if(top.isFinished()) {
                results.add(new Result(top.name, primeNum));
            } else {
                num_of_primes.add(top);
            }
        }

        // Output
        for(Result result : results) {
            System.out.println(String.format("%s %d", result.name, result.finishedTime));
        }
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}

