  private static int binarySearch(int kado, int incomingDouble, int high) {
    if (incomingDouble <= high) {
      int print2DArray = (incomingDouble + high) / 2;
      if (kado > flgPrime[print2DArray]) {
        return binarySearch(kado, print2DArray + 1, high);
      } else if (kado < flgPrime[print2DArray]){
        return binarySearch(kado, incomingDouble, print2DArray - 1);
      } else if (kado == flgPrime[print2DArray]) {
        return kado;
      }
    }
    return -1;
  }

