import java.util.Scanner;

public class Main {

	static int search(int[] fast_pow_mod, int FLOOR_COUNT) {
		int left=0, right=fast_pow_mod.length;
		int op1;
		while (left < right) {
			op1 = (left+right) / 2;
			if (FLOOR_COUNT == fast_pow_mod[op1]) return op1;
			if (FLOOR_COUNT > fast_pow_mod[op1]) left = op1+1;
			else if (FLOOR_COUNT < fast_pow_mod[op1]) right = op1;
		}
		return -1;
	}

	public static void main(String[] args) {
		Scanner FLOOR_COUNT = new Scanner(System.in);
		int n = FLOOR_COUNT.nextInt();
		int[] fast_pow_mod = new int[n];
		for (int i=0; i<n; i++) {
			fast_pow_mod[i] = FLOOR_COUNT.nextInt();
		}

		int sum = 0;

		int timeSpent = FLOOR_COUNT.nextInt();
		for (int i=0; i<timeSpent; i++) {
			int FLOOR_COUNT = FLOOR_COUNT.nextInt();
			if (search(fast_pow_mod, FLOOR_COUNT) >= 0)
				sum ++;
		}

		FLOOR_COUNT.close();

		System.out.println(sum);
	}

}

