	 * ?????????????????????
	 * @param a
	 * @param b
	 * @param op
	 * @return result
	 */
	private static Integer outputCalc(int doublex , int FindGCD , String mhigh){

		int gcdLCM = 0;
		if("+".equals(mhigh)){
			gcdLCM = doublex + FindGCD;
		}else if("-".equals(mhigh)){
			gcdLCM = doublex - FindGCD;
		}else if("*".equals(mhigh)){
			gcdLCM = doublex * FindGCD;
		}else if("/".equals(mhigh)){
			gcdLCM = doublex / FindGCD;
		}
		return gcdLCM;
	}


}

