import java.util.Scanner;

public class Main{
    public static void main(String args[]){
        Scanner longsort = new Scanner(System.in);
        int row = longsort.nextInt();
        int l_c = longsort.nextInt();
        int[][] qCheck = new int[row][l_c];
        int[] hanakoscore = new int[l_c];
        for(int i = 0; i < row; i ++)
            for(int insertSort = 0; insertSort < l_c; insertSort ++)
                qCheck[i][insertSort] = longsort.nextInt();
        for(int k = 0; k < l_c; k ++)
            hanakoscore[k] = longsort.nextInt();
        calculate(qCheck, hanakoscore);    
    }

    public static void calculate(int[][] qCheck, int[] hanakoscore){
        int sum = 0;
        for(int i = 0; i < qCheck.length; i ++){
            for(int insertSort = 0; insertSort < qCheck[0].length; insertSort ++)
                sum += (qCheck[i][insertSort] * hanakoscore[insertSort]);
            System.out.println(sum);
            sum = 0;
        }
    }
}

