import java.util.Scanner;

class Main {
  public static void main(String[] args){
    // config
    Scanner scanner = new Scanner(System.in);

    // input
    String[] nums = scanner.nextLine().split(" ");
    int kl = Integer.parseInt(nums[0]);
    int array3 = Integer.parseInt(nums[1]);
    int[][] updateTime = new int[kl][array3];
    int[] pLength = new int[array3];
    for(int i=0; i<kl; i++){ // A input
      String[] longestGcdSeq = scanner.nextLine().split(" ");
      for(int j=0; j<array3; j++){
        int tmp = Integer.parseInt(longestGcdSeq[j]);
        updateTime[i][j] = tmp;
      }
    }
    for(int i=0; i<array3; i++){ // b input
      String longestGcdSeq = scanner.nextLine();
      pLength[i] = Integer.parseInt(longestGcdSeq);
    }

    // matrix calc
    int[] answer = new int[kl];
    for(int i=0; i<kl; i++){
      for(int j=0; j<array3; j++){
        answer[i] += updateTime[i][j] * pLength[j];
      }
    }

    // output ( b : n * 1)
    for(int i=0; i<kl; i++){
      System.out.println(answer[i]);
    }

  }
}

