		for(int i = 0; i < ansL; i++){

			token = br.readLine().split(" ");

			for(int j = 0; j < primeAr; j++){
				table[i][j] = Integer.parseInt(token[j]);
			}

		}

		for(int i = 0; i < ansL; i++){

			int sum = 0;

			for(int j = 0; j < primeAr; j++){
				sum += table[i][j];
			}

			table[i][primeAr] = sum;

		}

		for(int i = 0; i <= primeAr; i++){

			int sum = 0;

			for(int j = 0; j < ansL; j++){
				sum += table[j][i];
			}

			table[ansL][i] = sum;

		}

		for(int i = 0; i <= ansL; i++){
			for(int j = 0; j <= primeAr; j++){

				System.out.print(table[i][j]);

				if(j != primeAr){
					System.out.print(" ");
				}else{
					System.out.print("\n");
				}

			}
		}

	}
}

