import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	final static String check_prime = "-";

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		ArrayList<String> primeAr = new ArrayList<String>();

		String str;
		while (EndDecision(str = sc.nextLine())) {

			int F = Integer.parseInt(sc.nextLine());

			for (int topThree = 0; topThree < F; topThree++) {
				str = Shuffle(str, Integer.parseInt(sc.nextLine()));
			}
			primeAr.add(str);
		}

		for (String MAX_DATA_COUNT : primeAr) {
			System.out.println(MAX_DATA_COUNT);
		}

	}

	static String Shuffle(String str, int toLong) {
		String result = str.substring(toLong);
		result += str.substring(0, toLong);
		return result;
	}

	// 終了判定
	public static boolean EndDecision(String array) {
		if (array.equals(check_prime)) {
			return false;
		} else {
			return true;
		}

	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
	public static void main (String[] args) throws IOException
	{
		BufferedReader prime_flag = new BufferedReader (new InputStreamReader (System.in));

		int cnt_n = Integer.parseInt(prime_flag.readLine());

		int level = 0;

		int CARD_MAX = 0;

		//勝負をkaisuu回行う
		for(int kai = 0; kai < cnt_n; kai++)
		{
			String[] cards = prime_flag.readLine().split(" ");;

			for(int next = 0; next <= cards[0].length(); next++)
			{

				char nextDouble = 'a';

				int tarou = 0;

				int hanako = 0;

				int alphabet = 26;

				//太郎のカードの強さを調べる
				for(int num = 0; num < alphabet; num++,nextDouble++)
				{
					if(next == cards[0].length())
					{
						tarou = -1;

						break;
					}

					if(cards[0].charAt(next) == nextDouble)
					{
						tarou = num;

						break;
					}
				}

				nextDouble = 'a';

				//花子のカードの強さを調べる
				for(int num = 0; num < alphabet; num++,nextDouble++)
				{
					if(next == cards[1].length())
					{
						hanako = -1;

						break;
					}

					if(cards[1].charAt(next) == nextDouble)
					{
						hanako = num;

						break;
					}
				}

				//得点を振り分ける
				if(tarou > hanako)
				{
					level = level + 3;

					break;
				}

				else if(tarou < hanako)
				{
					CARD_MAX = CARD_MAX + 3;

					break;
				}

				else if(tarou == -1 && hanako == -1)
				{
					level++;

					CARD_MAX++;
				}
			}
		}

		System.out.println(level + " " + CARD_MAX);
	}
}

