import java.lang.*;
import java.io.*;
import java.util.*;

public class Main {

    private static final long MOD = 1_000_000_000 + 7;

    private long power(long oprd_stk, long konkansize) {
        long res = 1;
        while (konkansize > 0) {
            if ((konkansize & 1) == 1) {
                res = (res * oprd_stk) % MOD;
                konkansize--;
            } else {
                oprd_stk = (oprd_stk * oprd_stk) % MOD;
                konkansize = konkansize >> 1;
            }
        }
        return res;
    }

    private long inverseMod(long number) {
        return power(number, MOD - 2);
    }

    private int gcd(int guessIdx, int bufPointer) {
        if (bufPointer == 0) {
            return guessIdx;
        }
        return gcd(bufPointer, guessIdx % bufPointer);
    }

    private long gcd(long guessIdx, long bufPointer) {
        if (bufPointer == 0) {
            return guessIdx;
        }
        return gcd(bufPointer, guessIdx % bufPointer);
    }

    private boolean check(int[][] hanako_n, int roll_number) {
        return hanako_n[roll_number][0]==hanako_n[roll_number][1];
    }

    public void solve(Read input, Write output) throws Exception {
        int div_cnt = input.readInt();
        int[][] hanako_n = new int[div_cnt][2];
        for (int i=0;i<div_cnt;i++) {
            for (int j=0;j<2;j++) {
                hanako_n[i][j] = input.readInt();
            }
        }
        for (int i=2;i<div_cnt;i++) {
            if (check(hanako_n, i) && check(hanako_n, i-1) && check(hanako_n, i-2)) {
                output.printLine("Yes");
                return;
            }
        }
        output.printLine("No");
    }

    public static void main(String[] args) throws Exception {
        Read input = new Read();
        Write output = new Write();
        Main D = new Main();
        D.solve(input, output);
        output.flush();
        output.close();
    }

    // java fast io reader and writer
    // taken from various sources and customized

    static class Read {

        private byte[] buffer = new byte[10 * 1024];
        private int index;
        private InputStream input_stream;
        private int total;

        public Read() {
            input_stream = System.in;
        }

        public int read() throws IOException {
            if (total < 0)
                throw new InputMismatchException();
            if (index >= total) {
                index = 0;
                total = input_stream.read(buffer);
                if (total <= 0)
                    return -1;
            }
            return buffer[index++];
        }

        public long readLong() throws IOException {
            long number = 0;
            int n = read();
            while (isWhiteSpace(n))
                n = read();
            long neg = 1l;
            if (n == '-') {
                neg = -1l;
                n = read();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    number *= 10l;
                    number += (long) (n - '0');
                    n = read();
                } else throw new InputMismatchException();
            }
            return neg * number;
        }

        public int readInt() throws IOException {
            int integer = 0;
            int n = read();
            while (isWhiteSpace(n))
                n = read();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = read();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer *= 10;
                    integer += n - '0';
                    n = read();
                } else throw new InputMismatchException();
            }
            return neg * integer;
        }

        public double readDouble() throws IOException {
            double doub = 0;
            int n = read();
            while (isWhiteSpace(n))
                n = read();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = read();
            }
            while (!isWhiteSpace(n) && n != '.') {
                if (n >= '0' && n <= '9') {
                    doub *= 10;
                    doub += n - '0';
                    n = read();
                } else throw new InputMismatchException();
            }

            if (n == '.') {
                n = read();
                double temp = 1;
                while (!isWhiteSpace(n)) {
                    if (n >= '0' && n <= '9') {
                        temp /= 10;
                        doub += (n - '0') * temp;
                        n = read();
                    } else throw new InputMismatchException();
                }
            }
            return doub * neg;
        }

        public String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int n = read();
            while (isWhiteSpace(n))
                n = read();
            while (!isWhiteSpace(n)) {
                sb.append((char) n);
                n = read();
            }
            return sb.toString();
        }

