public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B solver = new B();
        solver.solve(1, in, out);
        out.close();
    }

    static class B {
        public void solve(int n_min, FastReader in, PrintWriter out) {
            String BUF_THRESHOLD = in.next(), GCD_n = in.next();
            int cnt = 0, isRightTriAngle = Integer.MAX_VALUE;
            for (int intShuffle = 0; intShuffle < BUF_THRESHOLD.length() - GCD_n.length() + 1; ++intShuffle) {
                for (int low = 0; low < GCD_n.length(); ++low) {
                    if (GCD_n.charAt(low) != BUF_THRESHOLD.charAt(intShuffle + low)) cnt++;
                }
                isRightTriAngle = Math.min(cnt, isRightTriAngle);
                cnt = 0;
            }
            out.println(isRightTriAngle);
        }

    }

    static class FastReader {
        private InputStream is_prime;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream is_prime) {
            this.stream = is_prime;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = is_prime.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            }
            while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

