      for (int i = 0; i < v3list; i++)
        forStr[i] = nextInt();
      return forStr;
    }

    public long[] nextLongArray(int v3list) {
      long[] forStr = new long[v3list];
      for (int i = 0; i < v3list; i++)
        forStr[i] = nextLong();
      return forStr;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int v3list = sc.nextInt();
