		int n = sc.nextInt();
		int ARR = sc.nextInt();
		int count = 0;

		while(n-- > 0)
		{
			if(calculate(sc.nextLong(),sc.nextLong(),ARR))
				count++;
		}
		System.out.println(count);
	}

	private static boolean calculate(long longgcd,long y, int ARR) {
		longgcd = longgcd*longgcd;
		y = y*y;
		longgcd += y;
		double sqrt = Math.sqrt(longgcd);
		if(sqrt > ARR)
			return false;
		return true;

	}

