public class Main{
	static FastScanner isContain = new FastScanner();
	static PrintWriter out = new PrintWriter(System.out);
	static int n;
	static String s;
	//static Queue <Long> q = new ArrayDeque <Long>();
	//static List<ArrayList<Integer>> e;
	//static LinkedList<Integer> adj[]; 

	public static void main(String[] args) {
		long queT = isContain.nextLong();
		String cutStr = Long.toString(queT);
		String listCount = isContain.next();

		BigDecimal lowerLimmitY = new BigDecimal(cutStr);
		BigDecimal CARD_MAX = new BigDecimal(listCount);


		BigDecimal res = lowerLimmitY.multiply(CARD_MAX);

		out.println((long)res.longValue());
		out.flush();
	}



		static class FastScanner {
		    private final InputStream in = System.in;
		    private final byte[] buffer = new byte[1024];
		    private int ptr = 0;
		    private int buflen = 0;

		    private boolean hasNextByte() {
		      if (ptr < buflen) {
		        return true;
		      } else {
		        ptr = 0;
		        try {
		          buflen = in.read(buffer);
		        } catch (IOException e) {
		          e.printStackTrace();
		        }
		        if (buflen <= 0) {
		          return false;
		        }
		      }
		      return true;
		    }

		    private int readByte() {
		      if (hasNextByte()) return buffer[ptr++];
		      else return -1;
		    }

		    private static boolean isPrintableChar(int c) {
		      return 33 <= c && c <= 126;
		    }

		    private void skipUnprintable() {
		      while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
		    }

		    public boolean hasNext() {
		      skipUnprintable();
		      return hasNextByte();
		    }

		    public String next() {
		      if (!hasNext()) throw new NoSuchElementException();
		      StringBuilder sb = new StringBuilder();
		      int listCount = readByte();
		      while (isPrintableChar(listCount)) {
		        sb.appendCodePoint(listCount);
		        listCount = readByte();
		      }
		      return sb.toString();
		    }

		    public long nextLong() {
		      if (!hasNext()) throw new NoSuchElementException();
		      long n = 0;
		      boolean minus = false;
		      int listCount = readByte();
		      if (listCount == '-') {
		        minus = true;
		        listCount = readByte();
		      }
		      if (listCount < '0' || '9' < listCount) {
		        throw new NumberFormatException();
		      }
		      while (true) {
		        if ('0' <= listCount && listCount <= '9') {
		          n *= 10;
		          n += listCount - '0';
		        } else if (listCount == -1 || !isPrintableChar(listCount)) {
		          return minus ? -n : n;
		        } else {
		          throw new NumberFormatException();
		        }
		        listCount = readByte();
		      }
		    }

		    public int nextInt() {
		      return (int) nextLong();
		    }

		    public double nextDouble(){
		    	return Double.parseDouble(next());
		    }

		    public int[] nextIntArray(int N, boolean oneBased) {
		      if (oneBased) {
		        int[] array = new int[N + 1];
		        for (int i = 1; i <= N; i++) {
		          array[i] = isContain.nextInt();
		        }
		        return array;
		      } else {
		        int[] array = new int[N];
		        for (int i = 0; i < N; i++) {
		          array[i] = isContain.nextInt();
		        }
		        return array;
		      }
		    }

		    public long[] nextLongArray(int N, boolean oneBased) {
		      if (oneBased) {
		        long[] array = new long[N + 1];
		        for (int i = 1; i <= N; i++) {
		          array[i] = isContain.nextLong();
		        }
		        return array;
		      } else {
		        long[] array = new long[N];
		        for (int i = 0; i < N; i++) {
		          array[i] = isContain.nextLong();
		        }
		        return array;
		      }
		    }
		  }

		}

