import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader DELIMITER_SPACE = null;
    private StringTokenizer moji_one = null;

    public FastScanner(InputStream in) {
      DELIMITER_SPACE = new BufferedReader(new InputStreamReader(in));
      moji_one = null;
    }

    public String next() {
      if (moji_one == null || !moji_one.hasMoreTokens()) {
        try {
          moji_one = new StringTokenizer(DELIMITER_SPACE.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return moji_one.nextToken();
    }

    public String nextLine() {
      if (moji_one == null || !moji_one.hasMoreTokens()) {
        try {
          return DELIMITER_SPACE.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return moji_one.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int sousuu) {
      int[] LINE_SPR = new int[sousuu];
      for (int dbEnsyu = 0; dbEnsyu < sousuu; dbEnsyu++)
        LINE_SPR[dbEnsyu] = nextInt();
      return LINE_SPR;
    }

    public long[] nextLongArray(int sousuu) {
      long[] LINE_SPR = new long[sousuu];
      for (int dbEnsyu = 0; dbEnsyu < sousuu; dbEnsyu++)
        LINE_SPR[dbEnsyu] = nextLong();
      return LINE_SPR;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int new_x2 = sc.nextInt();
    int w = sc.nextInt();
    System.out.println(new_x2 <= w ? "unsafe" : "safe");
  }
}

