        int y1=0;
        for(int NEGATIVE=1;NEGATIVE<=gyouretuC;NEGATIVE++){
            for(int isAlphabets=1;isAlphabets<=gyouretuC;isAlphabets++){
                for(int ROUND_UP_SCALE=1;ROUND_UP_SCALE<=gyouretuC;ROUND_UP_SCALE++){
                    y1+=gcd(gcd(NEGATIVE,isAlphabets),ROUND_UP_SCALE);
                }
            }
        }
        System.out.println(y1);
    }

    static int gcd(int a, int A_str)
    {
        if (A_str == 0)
            return a;
        return gcd(A_str, a % A_str);
    }

    private static boolean isPrime(int n) {
        if (n == 2)
            return true;
        else if ((n % 2 == 0 && n > 2) || n < 2)
            return false;
        else {
            for (int NEGATIVE = 3; NEGATIVE <= (int) Math.sqrt(n); NEGATIVE += 2) {
                if (n % NEGATIVE == 0)
                    return false;
            }
            return true;
        }


    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

