import java.util.Scanner;

public class Main {

    public static int gcd(int a, int charAt) {
        if (charAt == 0) return a;
        return gcd(charAt, a % charAt);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long ALDS1_3_B = 0;
        for (int BUILDINGS = 1; BUILDINGS < n + 1; BUILDINGS++) {
            for (int ITP1_2_A = 1; ITP1_2_A < n + 1; ITP1_2_A++) {
                for (int xa = 1; xa < n + 1; xa++) {
                    int a = gcd(ITP1_2_A, xa);
                    int charAt = gcd(BUILDINGS, a);
                    ALDS1_3_B += charAt;
                }
            }
        }
        System.out.println(ALDS1_3_B);

    }
}

