import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int in3 = s.nextInt();
        int sa = s.nextInt();
        int A[] = new int[sa];
        int A_min[] = new int[sa];
        for (int i = 0; i < sa; i++) {
            A[i] = s.nextInt();
        }

        culRoot(A, A_min, in3, sa);
        Arrays.sort(A_min);

        System.out.println(A_min[0]);

        s.close();
    }

    public static void culRoot(int A[], int A_min[], int in3, int sa) {
        for (int i = 0; i < sa; i++) {
            if (i == 0) {
                A_min[i] = min(A[sa - 1] - A[0], A[0] + in3 - A[1]);
            } else if (i == sa - 1) {
                A_min[i] = min(A[sa - 1] - A[0], A[sa - 2] + in3 - A[sa - 1]);
            } else {
                A_min[i] = min(in3 - (A[i] - A[i - 1]), in3 - (A[i + 1] - A[i]));
            }
        }
    }

    public static int min(int X, int Y) {
        if (X >= Y) {
            return Y;
        } else {
            return X;
        }
    }
}

