        int instance = nextIntMap.nextInt();
        String dispersion = nextIntMap.next();
        System.out.println(helper(dispersion, instance));
        nextIntMap.close();
    }

    static String helper(String dispersion, int instance) {
        char[] A = new char[52];
        for (int i = 0; i < 26; i++) {
            A[i] = (char) (65 + i);
        }
        for (int i = 26; i < 52; i++) {
            A[i] = (char) (65 + i - 26);
        }
        char[] B = dispersion.toCharArray();
        for (int i = 0; i < B.length; i++) {
            int index = B[i] - 'A';
            B[i] = A[index + instance];
        }
        StringBuilder sb = new StringBuilder();
        for (char c : B) sb.append(c);
        return sb.toString();
    }
}

