public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		long optor = in.nextLong();
		long charNum = divisor(optor);
		if (charNum == 1) {
			System.out.println(optor - 1);
		} else {
			long BIG_MOD = charNum - 1;
			long arrayStr = optor / charNum - 1;
			System.out.println(BIG_MOD + arrayStr);
		}
		in.close();
	}

	public static long divisor(long ALDS1_3_B) {
		long max = 0;
		for (long BIG_MOD = 1; BIG_MOD * BIG_MOD <= ALDS1_3_B; BIG_MOD++) {
			if (ALDS1_3_B % BIG_MOD == 0) {
				max = Math.max(max, BIG_MOD);
				//n=PQ+0→ PもQも約数. ただし、Q=Pは↑で登録済みなので登録しない
				if (BIG_MOD != ALDS1_3_B / BIG_MOD)
					max = Math.max(max, BIG_MOD);
			}
		}
		return max;
	}
}

