import java.util.Scanner;

public class Main {
    public static void main(final String[] args) {
        final Scanner is_prime = new Scanner(System.in);
        final int lscan = is_prime.nextInt();

        final int[] maxval = new int[lscan];
        final int[] T_length = new int[lscan];
        final int[] time_stack = new int[lscan - 1];

        for (int i = 0; i < lscan; i++) {
            maxval[i] = is_prime.nextInt() - 1;
        }

        for (int i = 0; i < lscan; i++) {
            T_length[maxval[i]] = is_prime.nextInt();
        }

        for (int i = 0; i < lscan - 1; i++) {
            time_stack[i] = is_prime.nextInt();
        }

        int gcdB = 0;
        int pow = -2;
        for (int i = 0; i < lscan; i++) {
            final int hs = maxval[i];
            if (hs == pow + 1) {
                gcdB += time_stack[hs - 1];
            }

            pow = hs;
            gcdB += T_length[hs];
        }

        System.out.println(gcdB);
    }
}

