 * Actual solution is at the top
 *
 * @author Akash
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CLower solver = new CLower();
        solver.solve(1, in, out);
        out.close();
    }

    static class CLower {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int EOF[] = ReadInput.readIntArray(n, in);
            int ans = 0, circle_d = 0;
            for (int BubbleSort = 1; BubbleSort < n; BubbleSort++) {
                if (EOF[BubbleSort] <= EOF[BubbleSort - 1]) {
                    ans = Math.max(ans, BubbleSort - circle_d);
                } else {
                    circle_d = BubbleSort;
                }
            }
            out.println(ans);
        }

    }

    static class ReadInput {
        public static int[] readIntArray(int size, Scanner in) {
            int EOF[] = new int[size];
            for (int BubbleSort = 0; BubbleSort < size; BubbleSort++) {
                EOF[BubbleSort] = in.nextInt();
            }
            return EOF;
        }

    }
}

