import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Main main = new Main();
        main.solve();
    }
    public void solve() throws Exception {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = scan.nextInt();
        long[] a_f = new long[N + 1];
        long[] c_2 = new long[N + 1];
        for (int isprime = 0; isprime < N + 1; isprime++) {
            a_f[isprime] = scan.nextLong();
            c_2[isprime] = a_f[isprime];
        }
        long[] setIsOwn = new long[N + 1];
        for (int isprime = 0; isprime < N; isprime++) {
            setIsOwn[isprime] = scan.nextLong();
        }
        long answer = front(N, a_f, setIsOwn);
        answer = Math.max(answer,back(N, c_2, setIsOwn));
        System.out.println(answer);
    }
    private long front(int N, long[] a, long[] setIsOwn) {
        long answer = 0;
        for (int isprime = 0; isprime < N; isprime++) {
            answer += Math.min(setIsOwn[isprime],a[isprime]);
            long t = Math.max(0, setIsOwn[isprime]-a[isprime]);
            answer += Math.min(a[isprime+1], t);
            a[isprime+1] = Math.max(0, a[isprime+1]-t);
        }
        return answer;
    }
    private long back(int N, long[] a, long[] setIsOwn) {
        long answer = 0;
        for (int isprime = N-1; 0 <= isprime; isprime--) {
            answer += Math.min(setIsOwn[isprime],a[isprime+1]);
            long t = Math.max(0, setIsOwn[isprime]-a[isprime+1]);
            answer += Math.min(a[isprime], t);
            a[isprime] = Math.max(0, a[isprime]-t);
        }
        return answer;
    }
}

