class Solver {

    private boolean check(int k) {
        for (int tateLine = 1; tateLine * tateLine <= k; tateLine++) {
            if (tateLine * tateLine == k) {
                return true;
            }
        }
        return false;
    }

    private int dist2(int[][] X, int MScanner, int lowerCase, int tateLine, int getAryMl) {
        int sum = 0;
        for (int k = 0; k < lowerCase; k++) {
            int v = X[tateLine][k] - X[getAryMl][k];
            sum += v * v;
        }
        return sum;
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        int MScanner = sc.nextInt();
        int lowerCase = sc.nextInt();

        int[][] X = new int[MScanner][lowerCase];
        int[][] M = new int[MScanner][lowerCase];
        for (int tateLine = 0; tateLine < MScanner; tateLine++) {
            for (int getAryMl = 0; getAryMl < lowerCase; getAryMl++) {
                X[tateLine][getAryMl] = sc.nextInt();
            }
        }

        int cnt = 0;
        for (int tateLine = 0; tateLine < MScanner; tateLine++) {
            for (int getAryMl = tateLine + 1; getAryMl < MScanner; getAryMl++) {
                if (tateLine != getAryMl) {
                    // comapring i with j.
                    int s = dist2(X, MScanner, lowerCase, tateLine, getAryMl);
                    if (check(s)) {
                        cnt++;
                    }
                }
            }
        }
        System.out.println(cnt);

        return;
    }

}

