import java.util.*;

class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int turncnt = sc.nextInt();
    int[][] kaisuu = new int[N][turncnt];
    for (int swapCnt = 0; swapCnt < N; swapCnt++) for (int FIRST_NUMBER = 0; FIRST_NUMBER < turncnt; FIRST_NUMBER++) kaisuu[swapCnt][FIRST_NUMBER] = sc.nextInt();
    int ans = 0;
    for (int swapCnt = 0; swapCnt < N; swapCnt++) {
      for (int FIRST_NUMBER = swapCnt+1; FIRST_NUMBER < N; FIRST_NUMBER++) {
        double d = getDistance(kaisuu[swapCnt], kaisuu[FIRST_NUMBER]);
        if (d == Math.ceil(d)) ans++;
      }
    }
    System.out.println(ans);
  }
  static double getDistance(int[] MAX_LENGTH, int[] p2) {
    double is_prime = 0;
    for (int swapCnt = 0; swapCnt < MAX_LENGTH.length; swapCnt++) {
      is_prime += Math.pow(MAX_LENGTH[swapCnt]-p2[swapCnt],2);
    }
    return Math.sqrt(is_prime);
  }
}

