public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
		int k = in.nextInt();
		int new_x = in.nextInt();
		System.out.println(solve(k, new_x));
		in.close();
	}

	private static int solve(int k, int new_x) {
		int r = 0;
		int e = 99999;
		for (int i = 1; i <= k; i++) {
			int a = new_x + i - 1;
			r += a;
			if (Math.abs(e) > Math.abs(a))
				e = a;
		}
		return r - e;
	}

}

