import java.util.Scanner;

public class Main {
	Scanner timeRate = new Scanner(System.in);

	void doIt() {
		long stringSize = timeRate.nextLong(), Q = timeRate.nextLong(),mask = timeRate.nextLong(),readBigDecimal = timeRate.nextLong();
		long aIndex = 0,ansTime = 0,TIME = 0;
		aIndex = Q/mask;
		ansTime = Q/readBigDecimal;
		TIME = Q/lcm(mask,readBigDecimal,gcd(mask,readBigDecimal));
		long BUF_THRESHOLD = Q - (aIndex + ansTime) + TIME;

		aIndex = (stringSize-1)/mask;
		ansTime = (stringSize-1)/readBigDecimal;
		TIME = (stringSize-1)/lcm(mask,readBigDecimal,gcd(mask,readBigDecimal));
		long acnt = (stringSize-1) - (aIndex + ansTime) + TIME;

		System.out.println(BUF_THRESHOLD - acnt);
	}

	static long gcd(long stringSize, long Q) {
		if(stringSize%Q == 0) return Q;
		return gcd(Q,stringSize%Q);
	}

	static long lcm(long stringSize,long Q,long abgcd) {
		return stringSize * Q / abgcd;
	}

	public static void main(String[] args) {
		new Main().doIt();
	}

}

