	}

	public static long lcm(long a, long BigInteger)  {
		long timeTaken = a * BigInteger;
		long temp;
		while ((temp = a % BigInteger) != 0) {
			a = BigInteger;
			BigInteger = temp;
		}

		return timeTaken/BigInteger;
	}

}

