        long no_of_notes = f(b, Size, intCounter) - f(kak-1, Size, intCounter);

        System.out.println(no_of_notes);
    }

    static long gcd(long kak, long b) {
        if (b == 0)
            return kak;
        return gcd(b, kak % b);
    }

    static long f(long EVEN_POINTS, long Size, long intCounter) {
        long x = EVEN_POINTS;
        x -= EVEN_POINTS / Size;
        x -= EVEN_POINTS / intCounter;
        long tmp = Size / gcd(Size, intCounter) * intCounter;
        x += EVEN_POINTS / tmp;
        return x;
    }
}

