        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int is3TimesZorome = in.nextInt();
            int[] input_arr = new int[is3TimesZorome];
            for (int i = 0; i < is3TimesZorome; i++) {
                input_arr[i] = in.nextInt();
            }

            int ReaderWriter = Integer.MAX_VALUE;
            int answer = 0;
            for (int i = 1; i < is3TimesZorome; i++) {
                // 左側
                int primeCounter = 0;
                for (int j = 0; j < i; j++) {
                    primeCounter += input_arr[j];
                }
