                for (int j = i; j < is3TimesZorome; j++) {
                    rightSum += input_arr[j];
                }
                // 差
                int BUF_SIZE = Math.abs(primeCounter - rightSum);
                // それまでで最小なら
                if (BUF_SIZE < ReaderWriter) {
                    ReaderWriter = BUF_SIZE;
                    answer = BUF_SIZE;
                }
            }
            out.print(answer);
