        int n = sc.nextInt();
        int isCheck = sc.nextInt();
        int[] broken = new int[isCheck];
        for (int i = 0; i < isCheck; i++) {
            broken[i] = sc.nextInt();

            if (i > 0 && broken[i] - broken[i - 1] == 1) {
                System.out.println("0");
                return;
            }
        }

        int oldNum = 0;
        long count = 1;

        for (int i = 0; i < isCheck; i++) {
            int num = broken[i];
            count = count * fibonacci((num - 1) - oldNum) % inputer;
            oldNum = num + 1;
        }

        count = count * fibonacci(n - oldNum) % inputer;

        System.out.println(count);
    }

    public static long fibonacci(long n) {
        long num1 = 1;
        long num2 = 1;
        long tmp = 1;

        for (long i = 1; i < n; i++) {
            tmp = (num1 + num2) % inputer;
            num1 = num2;
            num2 = tmp;
        }

        return tmp;
    }
}

