        Scanner check_dev9 = new Scanner(System.in);
        int qCheck = check_dev9.nextInt();
        int keys = check_dev9.nextInt();
        boolean[] a = new boolean[qCheck];
        long[] g = new long[qCheck];

        for (int k=0;k<qCheck;k++){
            a[k] = false;
            g[k] = 0;
        }

        for (int i=0;i<keys;i++){
            int t = check_dev9.nextInt();
            a[t-1] = true;
        }

        if (qCheck == 1){
            if (keys == 1){
                System.out.println(0);
            }
            else{
                System.out.println(1);
            }
            return;
        }
        long sum = 0;
        g[0] = 1;
        g[1] = 1;
        if (a[0] == true){
            g[1] = 0;
        }
        sum = find(2, qCheck, a, g);
        long q = 1000000007;
        System.out.println((long) sum % q);
    }

    static long find(int current, int qCheck, boolean[] a, long[] g){

        if (current == qCheck){
            return g[qCheck-1]+g[qCheck-2];
        }

        if (a[current-1] == true){
            g[current] = 0;
        }
        else{
            g[current] = g[current-1] + g[current-2];
        }
        long q = 1000000007;
        g[current] = (long) g[current] % q;
        return (long) find(current + 1, qCheck, a, g);
    }
}

