class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte())
            return buffer[ptr++];
        else
            return -1;
    }

    private boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr]))
            ptr++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int Di2 = readByte();
        while (isPrintableChar(Di2)) {
            sb.appendCodePoint(Di2);
            Di2 = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext())
            throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int Di2 = readByte();
        if (Di2 == '-') {
            minus = true;
            Di2 = readByte();
        }
        if (Di2 < '0' || '9' < Di2) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= Di2 && Di2 <= '9') {
                n *= 10;
                n += Di2 - '0';
            } else if (Di2 == -1 || !isPrintableChar(Di2)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            Di2 = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

