class AtCoder {

    final int sizeT, start_time;

    AtCoder(FastScanner sc) {
        sizeT = sc.nextInt();
        start_time = sc.nextInt();
    }

    void solve(PrintWriter popAsInt) {
        if (sizeT == start_time) {
            popAsInt.println(sizeT + start_time);
        } else if (sizeT > start_time) {
            popAsInt.println(2 * sizeT - 1);
        } else {
            popAsInt.println(2 * start_time - 1);
        }
    }

