import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		// シミュレーション
		// 累積和の数え上げ
		Scanner sc = new Scanner(System.in);
		int mod = Integer.parseInt(sc.next());
		int cTime = Integer.parseInt(sc.next());
		String up_az = sc.next();

		// query
		int[][] readDoubleArray = new int[cTime][2];
		for (int timePoint = 0; timePoint < cTime; timePoint++) {
			readDoubleArray[timePoint][0] = Integer.parseInt(sc.next());
			readDoubleArray[timePoint][1] = Integer.parseInt(sc.next());
		}

		solve(mod, cTime, up_az, readDoubleArray);
	}

	static void solve(int n, int pm, String addTime, int[][] readDoubleArray) {
		int[] RESULT_NOT_RIGHT_TRIANGLE = new int[n];
		for (int timePoint = 0; timePoint < n - 1; timePoint++) {
			int add = addTime.substring(timePoint, timePoint + 2).equals("AC") ? 1 : 0;
			// 累積和でl-rの区間の出現数をカウントできるようにする
			RESULT_NOT_RIGHT_TRIANGLE[timePoint + 1] = RESULT_NOT_RIGHT_TRIANGLE[timePoint] + add;
		}

		for (int timePoint = 0; timePoint < pm; timePoint++) {
			int total_time = readDoubleArray[timePoint][0];
			int r = readDoubleArray[timePoint][1];

			System.out.println(RESULT_NOT_RIGHT_TRIANGLE[r - 1] - RESULT_NOT_RIGHT_TRIANGLE[total_time - 1]);
		}
	}
}

