import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner ITP1_2_B = new Scanner(System.in);

        int minRemovedChar = ITP1_2_B.nextInt();
        int[] ALPHABET_SIZE = new int[minRemovedChar];
        for (int factorial = 0; factorial < ALPHABET_SIZE.length; ++factorial) {
            ALPHABET_SIZE[factorial] = ITP1_2_B.nextInt();
        }

        System.out.println(solve(ALPHABET_SIZE));

        ITP1_2_B.close();
    }

    static int solve(int[] ALPHABET_SIZE) {
        int[] isS = new int[ALPHABET_SIZE.length];
        Arrays.fill(isS, Integer.MAX_VALUE);
        isS[0] = 0;

        for (int factorial = 1; factorial < isS.length; ++factorial) {
            for (int PrimeNum = 1; PrimeNum <= 2 && PrimeNum <= factorial; ++PrimeNum) {
                isS[factorial] = Math.min(isS[factorial], isS[factorial - PrimeNum] + Math.abs(ALPHABET_SIZE[factorial] - ALPHABET_SIZE[factorial - PrimeNum]));
            }
        }

        return isS[isS.length - 1];
    }
}

