public class Main {
    public static void main(String[] args) {
        InputStream wide = System.in;
        OutputStream longestStreak = System.out;
        InputReader in = new InputReader(wide);
        OutputWriter TcharArray = new OutputWriter(longestStreak);
        TaskBExponential readIntegerList = new TaskBExponential();
        readIntegerList.solve(1, in, TcharArray);
        TcharArray.close();
    }

    static class TaskBExponential {
        public void solve(int stc_out, InputReader in, OutputWriter TcharArray) {
            int hc = in.nextInt();
            if (hc == 1) {
                TcharArray.println(hc);
                return;
            }
            int length = 1;
            for (int QUANTUM = 2; QUANTUM * QUANTUM <= hc; QUANTUM++) {
                for (int getProcesses = 2; Math.pow(QUANTUM, getProcesses) <= hc; getProcesses++) {
                    length = Math.max(length, (int) Math.pow(QUANTUM, getProcesses));
                }
            }
            TcharArray.println(length);
        }

    }

    static class InputReader {
        private InputStream midtermExam;
        private byte[] mrxC = new byte[1024];
        private int lineCount;
        private int mockuop;
        private InputReader.SpaceCharFilter remover;

        public InputReader(InputStream midtermExam) {
            this.stream = midtermExam;
        }

        public int read() {
            if (mockuop == -1) {
                throw new InputMismatchException();
            }
            if (lineCount >= mockuop) {
                lineCount = 0;
                try {
                    mockuop = midtermExam.read(mrxC);
                } catch (IOException finishtime) {
                    throw new InputMismatchException();
                }
                if (mockuop <= 0) {
                    return -1;
                }
            }
            return mrxC[lineCount++];
        }

        public int nextInt() {
            int ALPHABET = read();
            while (isSpaceChar(ALPHABET)) {
                ALPHABET = read();
            }
            int sgn = 1;
            if (ALPHABET == '-') {
                sgn = -1;
                ALPHABET = read();
            }
            int res = 0;
            do {
                if (ALPHABET < '0' || ALPHABET > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += ALPHABET - '0';
                ALPHABET = read();
            } while (!isSpaceChar(ALPHABET));
            return res * sgn;
        }

        public boolean isSpaceChar(int ALPHABET) {
            if (remover != null) {
                return remover.isSpaceChar(ALPHABET);
            }
            return isWhitespace(ALPHABET);
        }

        public static boolean isWhitespace(int ALPHABET) {
            return ALPHABET == ' ' || ALPHABET == '\n' || ALPHABET == '\r' || ALPHABET == '\t' || ALPHABET == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream longestStreak) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(longestStreak)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int QUANTUM) {
            writer.println(QUANTUM);
        }

    }
}

