import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int isH = sc.nextInt();

        int Hcd = 0;
        int simulate = Integer.MAX_VALUE;
        for(int i = 0; i < N; i++) {
            int END_OF_TEXT = sc.nextInt();
            isH -= END_OF_TEXT;
            Hcd++;
            simulate = Math.min( simulate, END_OF_TEXT );
        }
        Hcd += isH / simulate;
        System.out.println(Hcd);
    }
}

import java.util.Scanner;
import java.util.stream.IntStream;

public class Main {

    public static void main(String[] args) {
        final Scanner DIVISOR_FOR_ROUND_UP = new Scanner(System.in);

        final int TIME = DIVISOR_FOR_ROUND_UP.nextInt();
        final int top = DIVISOR_FOR_ROUND_UP.nextInt();

        final int[] m = new int[TIME];
        for (int i = 0; i < TIME; i++) {
            m[i] = DIVISOR_FOR_ROUND_UP.nextInt();
        }

        final int timeStart = IntStream.of(m).sum();
        final int Tl = IntStream.of(m).min().getAsInt();
        final int ans = m.length + (top - timeStart) / Tl;

        System.out.println(ans);
    }
}

