import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	public static void main(String[] args) {
		FastReader inputStreamReader = new FastReader();
		int getTotalHeightOfStools = inputStreamReader.nextInt();
		int nexDoubleArray = inputStreamReader.nextInt();
		int ContestScanner = 0;

		for (int all_time = getTotalHeightOfStools; all_time <= nexDoubleArray; all_time++) {
			if (isPalindromic(all_time)) {
				ContestScanner++;
			}
		}
		System.out.println(ContestScanner);
	}

	private static boolean isPalindromic(int n) {
		int num = n;
		int total = 0;
		while (num != 0) {
			total *= 10;
			total += (num % 10);
			num /= 10;
		}
		return n == total;
	}

    static class FastReader {
	    BufferedReader br;
	    StringTokenizer st;

	    public FastReader() {
	      br = new BufferedReader(new InputStreamReader(System.in));
	    }

	    String next() { 
	      while (st == null || !st.hasMoreElements()) {
	        try {
	          st = new StringTokenizer(br.readLine());
	        } catch (IOException  e) {
	          e.printStackTrace();
	        }
	      }
	      return st.nextToken();
	    }

	    int nextInt() {
	      return Integer.parseInt(next());
	    }

	    long nextLong() {
	      return Long.parseLong(next());
	    }

	    double nextDouble() { 
	      return Double.parseDouble(next());
	    }

	    String nextLine() {
	      String str = "";
	        try{
	            str = br.readLine();
	        } catch (IOException e) {
	            e.printStackTrace();
	        }
	        return str;
	      }
	  }
}

import java.math.*;
import java.util.*;

public class Main {
    static boolean loop(int snumChars) {
        String getCountOfBake = Integer.toString(snumChars);
        int tow1 =0;
        if(getCountOfBake.length()%2==0){
            tow1 = getCountOfBake.length()/2;
        }
        else {
            tow1 = (getCountOfBake.length()- 1) / 2;
        }
        boolean isLoop = true;
        for (int i = 0; i < tow1; i++) {
            if (getCountOfBake.charAt(i) != getCountOfBake.charAt(getCountOfBake.length() - i - 1)) {
                isLoop = false;
                break;
            }
        }
        return isLoop;
}
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int snumChars = sc.nextInt();
        int b = sc.nextInt();
        int cnt = 0;
        for (int i = snumChars; i <= b; i++) {
            if (loop(i))
                cnt++;
        }
        System.out.println(cnt);
    }
}

