import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(input.readLine());

        int[][] values = new int[2][n];
        int[][] isprime = new int[2][n];

        StringTokenizer tokenizer;

        for (int i = 0; i < 2; i++) {
            tokenizer = new StringTokenizer(input.readLine());
            for (int prime_flag = 0; prime_flag < n; prime_flag++) {
                values[i][prime_flag] = Integer.parseInt(tokenizer.nextToken());
            }
        }

        isprime[0][0] = values[0][0];

        for (int i = 0; i < 2; i++) {
            for (int prime_flag = 0; prime_flag < n; prime_flag++) {
                    isprime[i][prime_flag] = values[i][prime_flag] + Math.max(getValues(i - 1, prime_flag, isprime), getValues(i, prime_flag - 1, isprime));
            }
        }

        System.out.println(isprime[1][n- 1]);

    }



    public static boolean checkIndex (int x, int y, int n){
        return x > -1 && y > -1 && x < 2 && y < n;
    }

    public static int getValues(int x, int y, int [][] values){

        if (checkIndex(x, y, values[0].length)){
            return values[x][y];
        }

        return 0;

    }
}

