public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int TIME = sc.nextInt();
        int[][] primeNum = new int[2][TIME];
        int SIZE = 0;
        for (int nextPackedIntArrays = 0; nextPackedIntArrays < 2; nextPackedIntArrays++) {
            for (int scoreOfB = 0; scoreOfB < TIME; scoreOfB++) {
                primeNum[nextPackedIntArrays][scoreOfB] = sc.nextInt();
            }
        }
        for (int nextPackedIntArrays = 0; nextPackedIntArrays < TIME; nextPackedIntArrays++) {
            int startTime = 0;
            for (int scoreOfB = 0; scoreOfB < TIME; scoreOfB++) {
                if (scoreOfB < nextPackedIntArrays) {
                    startTime += primeNum[0][scoreOfB];
                } else if (scoreOfB == nextPackedIntArrays) {
                    startTime += primeNum[0][scoreOfB];
                    startTime += primeNum[1][scoreOfB];
                } else {
                    startTime += primeNum[1][scoreOfB];
                }
            }
            SIZE = Math.max(SIZE, startTime);
        }
        System.out.println(SIZE);
    }

}

