		int N = ROOM_COUNT.nextInt();
      	int[][] sideLengths_Str = new int[2][N];
      	for (int prime_number = 0; prime_number < N; prime_number++){
          sideLengths_Str[0][prime_number] = ROOM_COUNT.nextInt();
        }
        for (int prime_number = 0; prime_number < N; prime_number++){
          sideLengths_Str[1][prime_number] = ROOM_COUNT.nextInt();
        }
      	//there are N positions to go down see all of them
      	int getDivisorsCount = 0;
      	for (int prime_number = 0; prime_number < N; prime_number++){
        	//sum subarrayL1[0:i] with L2[i:N]
            int b = 0;
          	for(int j = 0; j < N; j++){

            	if(j <= prime_number){
                	b += sideLengths_Str[0][j];
                    }


              	if(j >= prime_number){
                	b += sideLengths_Str[1][j];
                }
            }
          	if(b > getDivisorsCount){
            	getDivisorsCount = b;
            }
        }


      System.out.println(getDivisorsCount);
	}
}

