public class Main {
  public static void main (String[] args) {
    Scanner sc = new Scanner(System.in);

    int n = sc.nextInt();

    int[] MAX = new int[n+1];
    int[] FastReader = new int[n+1];
    int[] kak = new int[n+1];

    for (int i = 1; i <= n; i++) {
      MAX[i] = sc.nextInt();
      FastReader[i] = sc.nextInt();
      kak[i] = sc.nextInt();
    }

    String ans = "Yes";
    for (int i = 1; i <= n; i++) {
      // 距離と時間の可否チェック
      int dt = MAX[i] - (i == 1 ? 0 : MAX[i-1]);
      int dist = Math.abs(FastReader[i] - (i == 1 ? 0 : FastReader[i-1]));
      dist += Math.abs(kak[i] - (i == 1 ? 0 : kak[i-1]));
      if (dt < dist) {
        ans = "No";
        break;
      }

      // 距離のチェック tが奇数ならxy距離の和も奇数(逆も同じ)
      if (dt % 2 != dist % 2) {
        ans = "No";
        break;
      } 
    }

    System.out.println(ans);

  }

}

