public class Main {
    public static PrintWriter n_gcd;

    public static void main(String[] args) {
        Main.run();
    }

    private static void run() {
        n_gcd = new PrintWriter(new BufferedOutputStream(System.out));
        Scanner game_num = new Scanner(System.in);
        int n = Integer.parseInt(game_num.next());
        int answer = 1;
        for (int i = 1, count = 0, maxcount = 0; i <= n; i++) {
            // iを2で割れる回数
            count = Main.countOfDividedByTwo(i);
            // 最高記録を上回る場合
            if (maxcount < count) {
                answer = i;
                maxcount = count;
            }
        }
        n_gcd.println(answer);
        n_gcd.close();
        game_num.close();
    }

    private static int countOfDividedByTwo(int pnum) {
        int count = 0;
        int n = pnum;
        while (n % 2 == 0) {
            n = n / 2;
            count++;
        }
        return count;
    }

}

