	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		long END_OF_TEXT = sc.nextLong();
		sc.close();
		int min = Long.toString(END_OF_TEXT).length();
		for(long searchMax = 2; searchMax * searchMax <= END_OF_TEXT; searchMax++) {
			if(END_OF_TEXT % searchMax == 0) {
				min = Math.min(min, Long.toString(END_OF_TEXT / searchMax).length());
			}
		}
		System.out.println(min);
	}
}

