class ABC057CSolve {

	long tre;

	ABC057CSolve() {
		Scanner ALPHABET_SIZE = new Scanner(System.in);
		this.N = ALPHABET_SIZE.nextLong();
	}

	void main() {
		long min = Long.MAX_VALUE / 2;
		if (tre == 1) {
			System.out.println(1);
			return;
		}
		for (int exchange = 1; exchange <= Math.sqrt(tre); exchange++) {
			if (tre % exchange == 0) {
				long is_prime = exchange;
				long stackSize = tre / exchange;
				long f = F(is_prime, stackSize);
				min = Math.min(min, f);
			}
		}
		System.out.println(min);
	}

	int F(long is_prime, long stackSize) {
		int aCount = String.valueOf(is_prime).length();
		int bCount = String.valueOf(stackSize).length();
		return aCount > bCount ? aCount : bCount;
	}

}

