import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		long HH = Long.parseLong(sc.next());
		long a = 1;
		long ins = HH;
		ArrayList<Integer> list = new ArrayList<>();
		int min = String.valueOf(HH).length();
		if(Math.sqrt(HH) - (int)(Math.sqrt(HH)) == 0) {
		    min = String.valueOf((int)Math.sqrt(HH)).length();
		}else {
    		for(int i=2; i<=Math.sqrt(HH); i++) {
    		    if(ins % i == 0) {
    		        list.add(i);
    		        a *= i;
    		        ins /= i;
    		        i--;
    		    }
    		}


    		for(int i=0; i<Math.pow(2, list.size()); i++) {
    		    a = 1;
    		    ins = HH;
    		    for(int j=0; j<list.size(); j++) {
    		        if((1&i>>j) == 1) {a*=list.get(j); ins /= list.get(j);}
    		    }
    		    if(min > Math.max(String.valueOf(a).length(), String.valueOf(ins).length())) min = Math.max(String.valueOf(a).length(), String.valueOf(ins).length());
    		}
		}

		System.out.println(min);
	}
}

