import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

	// Atcoder用のサンプルプログラム
	public static void main(String[] args) {
		String line = "";
		try {
			line = readLine();

			StringTokenizer st = new StringTokenizer(line, " ");
			String pop = st.nextToken();
			String double_a = st.nextToken();

			int primeFactorize = Integer.parseInt(pop);
			int x_i = Integer.parseInt(double_a);
			int cnt = 0;
			// x y S-x-y
			for (int i = 0; i < x_i + 1; i++) {
				if (i > primeFactorize) {
					continue;
				}
				for (int j = 0; j < x_i + 1; j++) {
					if (j > primeFactorize) {
						continue;
					} else if (x_i - i - j > primeFactorize) {
						continue;
					}

					if (i + j <= x_i) {
						//System.out.println(String.valueOf(i) + "," + String.valueOf(j) + "," + String.valueOf(s - i - j));
						cnt++;
					}
				}
			}
			System.out.println(cnt);
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	private static String readLine() throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		return br.readLine();
	}

}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) throws Exception {
		Scanner not_prime = new Scanner(System.in);
		String TEMP_S = not_prime.next();

		String[] longNext = TEMP_S.split("");
		List<String> Gcd = new ArrayList<String>();
		for (int i = 0; i < longNext.length; i++) {
			if ("0".equals(longNext[i])) {
				Gcd.add("0");
			} else if ("1".equals(longNext[i])) {
				Gcd.add("1");
			} else {
				if (!(Gcd.size() == 0)) {
					Gcd.remove(Gcd.size() - 1);
				}
			}
		}
		for (String s : Gcd) {
			System.out.print(s);
		}
	}
}

