import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int N = scanner.nextInt();
		int L = scanner.nextInt();
		String[] circle_max_Y = new String[N];
		Map<String, String> map = new TreeMap<String,String>();
		for(int i=0;i<N;i++) {
			circle_max_Y[i] = scanner.next();
			if(map.get(circle_max_Y[i])==null) {
				map.put(circle_max_Y[i], circle_max_Y[i]);
			}
			else {
				map.put(circle_max_Y[i]+i, circle_max_Y[i]);
			}
		}
		L=L+1;
		for(String s:map.values()) {
			System.out.print(s);
		}
		System.out.println();
		scanner.close();
	}

}
